-- =============================================================================
-- V5: SEED 50 USERS & 100 LOGIN HISTORIES FOR AUTH SERVICE
-- =============================================================================

-- 1. Bảng lịch sử đăng nhập (Login History)
CREATE TABLE IF NOT EXISTS login_histories (
    id UUID PRIMARY KEY,
    user_id UUID,
    email VARCHAR(255) NOT NULL,
    ip_address VARCHAR(50),
    user_agent VARCHAR(500),
    status VARCHAR(20) NOT NULL,
    failure_reason VARCHAR(255),
    created_at TIMESTAMP WITH TIME ZONE NOT NULL
);

-- Gỡ bỏ ràng buộc foreign key (nếu bảng đã tồn tại từ trước) để triệt tiêu lỗi khóa ngoại 23503
ALTER TABLE login_histories DROP CONSTRAINT IF EXISTS login_histories_user_id_fkey;

CREATE INDEX IF NOT EXISTS idx_login_histories_email ON login_histories(email);
CREATE INDEX IF NOT EXISTS idx_login_histories_user_id ON login_histories(user_id);
CREATE INDEX IF NOT EXISTS idx_login_histories_created_at ON login_histories(created_at DESC);

-- 2. Thêm và chuẩn hóa người dùng
ON CONFLICT (email) DO UPDATE SET
    id = EXCLUDED.id,
    full_name = EXCLUDED.full_name,
    role = EXCLUDED.role,
    company_id = EXCLUDED.company_id,
    lms_user_id = EXCLUDED.lms_user_id,
    password_hash = EXCLUDED.password_hash,
    status = EXCLUDED.status,
    updated_at = NOW();

-- 3. Thêm 100 bản ghi Login History (Sử dụng SELECT id trực tiếp từ bảng users để bảo đảm đúng 100%)
ON CONFLICT (id) DO NOTHING;

